function container(){return{Id:'c'.repeat(64),Name:'/own',Image:'sha256:'+'d'.repeat(64),Config:{Labels:{'com.ssb.native-run':options.run}},RestartCount:0,State:{Status:'created',Running:false,Paused:false,Restarting:false,Dead:false,OOMKilled:false,Error:'',Pid:0,ExitCode:0,StartedAt:'0001-01-01T00:00:00Z',FinishedAt:'0001-01-01T00:00:00Z'}};}
function closure({Ctor=Native,mutate=()=>{},entry={},start=false,exit=0,finalMutate=()=>{},failure=null}={}){const n=new Ctor(options),x=container(),calls=[];mutate(x);if(start)Object.assign(x.State,{Status:'running',Running:true,Pid:123,StartedAt:'2026-10-09T20:00:00Z'});n.initial={containers:[]};n.proc={calls:[],assertClosed(){}};n.owned=[{id:x.Id,name:'own',image:x.Image,role:'probe',startRequested:start,...entry}];let inspections=0;n.d=async(args)=>{calls.push(args);n.proc.calls.push({closed:true});if(failure)throw failure;if(args[0]==='stop'){Object.assign(x.State,{Status:'exited',Running:false,Pid:0,ExitCode:exit,FinishedAt:'2026-10-09T20:01:00Z'});return{stdout:Buffer.from(x.Id)};}assert.deepEqual(args.slice(0,2),['container','inspect']);if(++inspections>1)finalMutate(x);return{stdout:Buffer.from(JSON.stringify([x]))};};return{n,calls,x};}
test('historical actual close rejects owned never-started container, corrected close classifies it without stop',async()=>{const Before=require(path.join(historical,'native.cjs')).Native,old=closure({Ctor:Before});await assert.rejects(old.n.close(true),e=>e.errors.some(x=>x.code==='container_completion_unverified'));const h=closure(),r=await h.n.close(true);assert.equal(r.verified,true);assert.equal(r.detail.outcomes[0].state,'never_started');assert.equal(r.detail.outcomes[0].exit,null);assert.equal(h.calls.length,2);assert.ok(h.calls.every(x=>x[0]!=='stop'));});
for(const [name,mutate,entry]of [
 ['nonzero start',x=>x.State.StartedAt='2026-10-09T20:00:00Z',{}],['missing start',x=>delete x.State.StartedAt,{}],['nonzero end',x=>x.State.FinishedAt='2026-10-09T20:00:00Z',{}],['restart',x=>x.RestartCount=1,{}],['missing restart',x=>delete x.RestartCount,{}],['paused',x=>x.State.Paused=true,{}],['dead',x=>x.State.Dead=true,{}],['error',x=>x.State.Error='SYNTHETIC_PRIVATE',{}],['exit',x=>x.State.ExitCode=137,{}],['pid',x=>x.State.Pid=3,{}],['start attempted',()=>{},{startRequested:true}],['start unknown',()=>{},{startRequested:undefined}],
])test('created rejects ambiguous history: '+name,async()=>{const h=closure({mutate,entry});await assert.rejects(h.n.close(true));assert.ok(h.calls.every(x=>x[0]!=='stop'));});
