async function helper({before=false,uid=1000,fault=null,payload,action='initialize',stateOwner=1000,stateMode=0o700,ancestorMode=0o711,toolsMode=0o755,importsOnly=false}={}){
 const tmp=fs.mkdtempSync(path.join(os.tmpdir(),'ssb-state-offline-')),root=path.join(tmp,'state');fs.mkdirSync(root,{mode:0o700});
 const fsModel={...fs,lstatSync(p){const s=fs.lstatSync(p);Object.defineProperty(s,'uid',{value:1000});return s;},fstatSync(fd){const s=fs.fstatSync(fd);Object.defineProperty(s,'uid',{value:1000});return s;}};
 const access=(owner,mode,required)=>{const bits=uid===owner?(mode>>6)&7:mode&7;if((bits&required)!==required)throw Object.assign(Error('SYNTHETIC_PRIVATE_DAC_PATH'),{code:'EACCES'});};
 for(const op of ['writeFileSync','mkdirSync'])fsModel[op]=(...args)=>{const p=String(args[0]);access(0,ancestorMode,1);access(stateOwner,stateMode,3);if(fault?.operation===op&&p.endsWith(fault.suffix))throw Object.assign(Error('SYNTHETIC_PRIVATE_PATH_AND_CONTENT'),{code:fault.code});return fs[op](...args);};
 // The bound TypeScript class executes unchanged after type erasure in the offline VM.
 const context=vm.createContext({process:{getuid:()=>uid},Buffer,performance,SharedArrayBuffer,Atomics,Int32Array,structuredClone});
 const module=new vm.SourceTextModule(stripTypeScriptTypes(fs.readFileSync(source,'utf8'),{mode:'transform'}),{context});
 await module.link(id=>{const values=id==='node:fs'?fsModel:require(id);return new vm.SyntheticModule(Object.keys(values),function(){for(const k of Object.keys(values))this.setExport(k,values[k]);},{context});});await module.evaluate();
 const file=path.join(before?historical:__dirname,'state-agent.cjs'),m={exports:{}},stdin=new EventEmitter(),stdout=[],stderr=[];
 const proc={getuid:()=>uid,stdin,stdout:{write:x=>stdout.push(x)},stderr:{write:x=>stderr.push(x)}};
 const req=id=>{if(id==='node:fs')return fsModel;if(id.endsWith('/maintenance-state.js')){access(0,ancestorMode,1);access(0,toolsMode,5);if(fault?.operation==='module')throw Object.assign(Error('SYNTHETIC_PRIVATE_MODULE_PATH'),{code:fault.code});return{MaintenanceState:module.namespace.MaintenanceState};}return require(id);};req.main=importsOnly?{}:m;
 vm.runInNewContext(fs.readFileSync(file,'utf8'),{require:req,module:m,exports:m.exports,process:proc,Buffer,__dirname:path.dirname(file)},{filename:file});
 const input={action,toolsRoot:'/synthetic-tools',binding:{root,service:'synthetic',generation:'seed'},owner:'synthetic-private-owner'};
 if(!importsOnly){stdin.emit('data',Buffer.from(payload===undefined?JSON.stringify(input):payload));stdin.emit('end');await new Promise(r=>setImmediate(r));}
 return{root,tmp,input,proc,stdout:stdout.join(''),stderr:stderr.join(''),run:m.exports.run};
}
test('actual stdin entry initializes exactly once; synthetic UID1000, real files and real state implementation',async()=>{const h=await helper();assert.equal(h.proc.exitCode,undefined);assert.deepEqual(JSON.parse(h.stdout),{epoch:0,syntheticNewService:true});assert.equal(h.stderr,'');const s=JSON.parse(fs.readFileSync(path.join(h.root,'runtime-state.json')));assert.equal(s.phase,'closed');assert.deepEqual(s.work,{});assert.equal(fs.statSync(path.join(h.root,'runtime-state.json')).mode&511,384);assert.equal(fs.statSync(path.join(h.root,'maintenance-window')).mode&511,448);assert.equal((await h.run({...h.input,action:'snapshot'})).phase,'closed');await assert.rejects(h.run(h.input),e=>e.code==='EEXIST');});
test('historical helper loses actual EACCES stage; new helper preserves only bounded code',async()=>{const fault={operation:'writeFileSync',suffix:'runtime-state.json',code:'EACCES'},old=await helper({before:true,fault}),next=await helper({fault});assert.equal(old.stderr,'state-operation-failed\n');assert.equal(old.proc.exitCode,1);assert.equal(next.proc.exitCode,1);assert.deepEqual(decodeState(next.stderr),{version:1,stage:'initialize-state',code:'EACCES'});assert.equal(next.stdout,'');assert.doesNotMatch(next.stderr,/PRIVATE|owner|PATH|CONTENT/);});
