test('actual controller preserves primary, exports bounded diagnosis and never-started cleanup, never full PASS',async()=>{const h=closure(),lines=[],primary=Object.assign(Error('SYNTHETIC_PRIVATE'),{code:'state_operation_failed',stateDiagnostic:{version:1,stage:'module',code:'EACCES'}});h.n.execute=async()=>{throw primary;};await assert.rejects(main({...options,output:x=>lines.push(x)},h.n),e=>e===primary);const r=lines.map(l=>JSON.parse(Buffer.from(l.split(' ')[1],'base64')));assert.equal(r[0].detail.failure.state.code,'EACCES');assert.equal(r.at(-1).detail.outcomes[0].state,'never_started');assert.equal(r.at(-1).ok,true);assert.throws(()=>parseReceipts(lines.join('\n'),options.run,SOURCE,options));const partial=parseReceipts(lines.join('\n'),options.run,SOURCE,options,{partial:true});assert.equal(partial.proof.status,'PARTIAL_FAILURE_RECEIVED');assert.doesNotMatch(lines.map(x=>Buffer.from(x.split(' ')[1],'base64').toString()).join(''),/SYNTHETIC_PRIVATE/);});
