 const n=new Native(options);n.proc=new m.exports.Processes({deadline:performance.now()+40000,privateRoot:writeFails?path.join(dir,'missing'):dir});n.synthetic={owner:'SYNTHETIC_PRIVATE'};n.toolsRoot='/synthetic-tools';n.resources=()=>{};
