 assert.equal(spawnArgs[0],process.execPath);assert.deepEqual(spawnArgs[1],require('./state-launch.cjs').stateArgs(path.join(__dirname,'state-agent.cjs')));assert.equal(spawnArgs[2].uid,1000);assert.equal(spawnArgs[2].gid,1000);n.proc.assertClosed();
